package com.taylordproductivty.med_timing_tracker.data

import androidx.room.Entity
import androidx.room.PrimaryKey

@Entity(tableName = "profiles")
data class Profile(
    @PrimaryKey(autoGenerate = true) val id: Int = 0,
    val name: String,
    val kind: ProfileKind = ProfileKind.PERSON,
    // Used by the one-tap "text caregiver" action (ACTION_SENDTO smsto:); null if not set.
    val phoneNumber: String? = null,
    val colorTag: String? = null,
    // Soft delete: keeps DoseLog history intact since DoseLog has no @ForeignKey to cascade.
    val isArchived: Boolean = false,
    val createdAt: Long = System.currentTimeMillis(),
)
